// Every failure (ingestion gap, eval below 90%, crashed node) becomes one queryable row in assistant_log.
const e = $input.first().json;
const ex = e.execution || {};
const wf = e.workflow || {};
const msg = (ex.error && (ex.error.message || ex.error.description)) || 'Unknown error';
return [{ json: {
  session_id: 'system',
  channel: 'system',
  question: 'Workflow failed: ' + (wf.name || wf.id || 'unknown'),
  status: 'error',
  answer: 'Failed at node: ' + (ex.lastNodeExecuted || 'unknown') + (ex.url ? ' | ' + ex.url : ''),
  error: String(msg).slice(0, 2000),
  source: wf.id || null
} }];

parameters.content:
## Incident log
Set as the Error Workflow of the 3 Cottonil workflows. Each production failure lands in public.assistant_log with channel = system, so failures are visible next to normal traffic.
Query: select * from assistant_log where channel = 'system' order by created_at desc;
